import re,glob,os,sys
targets={'src/transport/sessionResume.test.ts','src/transport/createServer.test.ts','src/transport/ws/validation.test.ts'}
pat=re.compile(r'\[validated by:? ([^\]]+)\]\(([^)#]+)#L(\d+)\)')
unmapped=[];changed=0
for md in glob.glob('**/*.md',recursive=True):
  if md.startswith('node_modules'): continue
  s=open(md).read()
  def fix(m):
    global changed
    title,rel,ln=m.groups()
    path=os.path.normpath(os.path.join(os.path.dirname(md),rel))
    if path not in targets: return m.group(0)
    lines=open(path).read().split('\n')
    hits=[i+1 for i,l in enumerate(lines) if title in l and re.search(r"\b(it|test)\(",l)]
    if not hits:
      # title may wrap onto the next line after it(
      hits=[i+1 for i,l in enumerate(lines) if title in l]
    if len(hits)!=1: unmapped.append((md,title,hits)); return m.group(0)
    if str(hits[0])!=ln: changed+=1
    return m.group(0).replace('#L'+ln,'#L'+str(hits[0]))
  n=pat.sub(fix,s)
  if n!=s: open(md,'w').write(n)
print('changed',changed); print('unmapped',unmapped)
EOF
